import React from "react";
import { Link } from "react-router-dom";
import { FaUser, FaEdit, FaHeadset } from "react-icons/fa";
import TechnicianNavbar from "../components/TechnicianNavbar";
import withRouter from "../common/withRouter";

// صفحه‌ی منوی حساب — پروفایل، بلاگ، دکمه‌ی شناور پشتیبانی
class AccountMenuPage extends React.Component {
  constructor(props) {
    super(props);
    this.handleSupportClick = this.handleSupportClick.bind(this);
  }

  handleSupportClick() {
    this.props.navigate("/chat");
  }

  render() {
    return (
      <div dir="rtl" lang="fa" className="bg-white min-vh-100 position-relative">
        <div className="container-fluid px-3 pt-4" style={{ maxWidth: 480, margin: "0 auto", paddingBottom: 100 }}>
          <Link
            to="/profile"
            className="d-flex align-items-center justify-content-between border rounded-4 px-3 py-3 mb-3 text-decoration-none"
          >
            <FaUser className="text-primary" size={22} />
            <span className="text-primary fw-semibold">پروفایل</span>
          </Link>

          <Link
            to="/blog"
            className="d-flex align-items-center justify-content-between border rounded-4 px-3 py-3 mb-3 text-decoration-none"
          >
            <FaEdit className="text-primary" size={22} />
            <span className="text-primary fw-semibold">بلاگ</span>
          </Link>
        </div>

        <button
          type="button"
          onClick={this.handleSupportClick}
          className="btn btn-primary rounded-pill d-flex align-items-center gap-2 px-4 py-2 position-fixed"
          style={{ bottom: 96, right: 24, boxShadow: "0 6px 16px rgba(0,0,0,0.2)" }}
        >
          <span>پشتیبانی</span>
          <FaHeadset size={18} />
        </button>

        <TechnicianNavbar />
      </div>
    );
  }
}

export default withRouter(AccountMenuPage);
